syntax:
// VALID contexts:
class C {
    void member_func() {
        int arr[sizeof(*this)];  // OK: inside member function
    }

    unsigned int sz = sizeof(*this);  // OK: brace-or-equal-initializer
};

// INVALID contexts:
class C {
    int arr[sizeof(*this)];  // ERROR: class scope, not in member function

    void func() {
        struct Inner {
            int x[sizeof(*this)];  // ERROR: *this refers to C, not Inner
        };
    }
};

code_example:
#include <iostream>

class Outer {
public:
    // ERROR: Cannot use sizeof(*this) at class scope for array bounds
    // int a[sizeof(*this)];  // Compilation error

    // OK: Brace-or-equal-initializer (C++11)
    unsigned int sz = sizeof(*this);

    // Store size to use for array
    static constexpr size_t outer_size = sizeof(Outer);
    int a[outer_size];  // Workaround: use sizeof(Outer) or constexpr

    void f() {
        // OK: Inside member function, this pointer exists
        int b[sizeof(*this)];
        std::cout << "Inside member function, sizeof(*this) = " 
                  << sizeof(*this) << "\n";
        std::cout << "Local array size: " << sizeof(b) << " bytes\n";

        // Nested local class
        struct Inner {
            // ERROR: *this would refer to Outer, not Inner
            // This context is not inside a member function of Inner
            // int c[sizeof(*this)];  // Compilation error

            // Workaround: Use sizeof(Inner) explicitly
            int c[sizeof(Inner)];
        };

        Inner inner;
        std::cout << "Inner object size: " << sizeof(Inner) << " bytes\n";
    }

    void demonstrate() {
        std::cout << "Outer size via member initializer: " << sz << " bytes\n";
    }
};

int main() {
    std::cout << "=== sizeof(*this) Context Rules ===\n\n";

    Outer obj;
    obj.demonstrate();
    obj.f();

    std::cout << "\nDirect sizeof(Outer): " << sizeof(Outer) << " bytes\n";

    return 0;
}

// Output:
// === sizeof(*this) Context Rules ===
//
// Outer size via member initializer: 12 bytes  <- OK: brace-or-equal-init
// Inside member function, sizeof(*this) = 12   <- OK: member function
// Local array size: 12 bytes
// Inner object size: 4 bytes                   <- Must use sizeof(Inner)
//
// Direct sizeof(Outer): 12 bytes
